            const splitRatio = studioState?.splitRatio !== undefined ? studioState.splitRatio : 80;
            const winner = ml.winner || null;
            const leaderboard = Array.isArray(ml.leaderboard) ? ml.leaderboard : [];
            const featImp = Array.isArray(ml.featureImportance) ? ml.featureImportance : [];
            const isReg = (ml.taskType === 'regression');

