                                    const prodVal = rawPt.production !== undefined ? rawPt.production : (dataset.rowCount ? Math.round(dataset.rowCount / seriesData.values.length) : '-');
                                    const defVal = rawPt.defects !== undefined ? rawPt.defects : '-';
                                    const isExceeded = val > uclVal;
